-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION inventory.scraps_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS scraps_insert_audit ON inventory.scraps;
CREATE TRIGGER scraps_insert_audit BEFORE INSERT ON inventory.scraps
    FOR EACH ROW EXECUTE FUNCTION inventory.scraps_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS scraps_update_audit ON inventory.scraps;
CREATE TRIGGER scraps_update_audit BEFORE UPDATE ON inventory.scraps
    FOR EACH ROW EXECUTE FUNCTION inventory.scraps_audit_timestamp();
